  for (const count of [numOnes, numZeros, numNegOnes]) {
    if (!Number.isInteger(count) || count < 0 || count > 50) return 'Each item count is an integer from 0 to 50.';
  }
  if (!Number.isInteger(k) || k < 0 || k > numOnes + numZeros + numNegOnes) return 'k is between 0 and the total number of items.';
  return null;
}

