function kItemsWithMaximumSum(numOnes, numZeros, numNegOnes, k) {
  // Try every split of k into a count of ones and a count of zeros; the rest must be -1s.
  let best = -Infinity;
  for (let a = 0; a <= numOnes; a++) {
    for (let b = 0; b <= numZeros; b++) {
      const c = k - a - b;
      if (c < 0 || c > numNegOnes) continue;
      best = Math.max(best, a - c);
    }
  }
  return best;
}

