function generate(rand, size) {
  const limit = size === 'large' ? 50 : 6;
  const pick = () => Math.floor(rand() * (limit + 1));
  const numOnes = pick();
  const numZeros = rand() < 0.2 ? 0 : pick();
  const numNegOnes = pick();
  const total = numOnes + numZeros + numNegOnes;
  const k = Math.floor(rand() * (total + 1));
  return [numOnes, numZeros, numNegOnes, k];
}
